input.sparql:
SELECT DISTINCT ?zone ?temp ?sp ?tsid ?setsid WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasTemperature ?temp .
  ?temp ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?zone brick:hasProperty ?sp . ?sp a brick:CoolingSetpoint . ?sp ref:hasTimeseriesId ?setsid }
}

SELECT DISTINCT ?class WHERE {
  ?x a ?class .
  FILTER (contains(lcase(str(?class)), "setpoint") || contains(lcase(str(?class)), "set_point"))
}

SELECT DISTINCT ?z ?zn ?temp ?tsref WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zn .
  OPTIONAL { ?z brick:hasTemperature ?temp . ?temp ref:hasExternalReference ?tsref }
}

SELECT DISTINCT ?z ?temp ?tsref WHERE {
  ?z a brick:Zone .
  ?z brick:hasTemperature ?temp .
  ?temp ref:hasExternalReference ?tsref .
}

SELECT DISTINCT ?z ?temp ?tsref WHERE {
  ?z a brick:HVAC_Zone .
  ?z ?p ?temp .
  ?temp a brick:Zone_Air_Temperature_Sensor .
  ?temp ref:hasExternalReference ?tsref .
}

SELECT DISTINCT ?z ?temp ?p WHERE {
  ?z a brick:HVAC_Zone .
  ?z ?p ?temp .
  ?temp a brick:Zone_Air_Temperature_Sensor .
}

SELECT DISTINCT ?z ?sp ?val WHERE {
  ?z a brick:HVAC_Zone .
  ?z brick:hasPoint ?sset .
  ?sset a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?sset qudt:value ?val .
}
